def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    vals = [v for v in np.unique(g) if v != bg]
    fg = vals[0] if vals else 0
    corners = [(0, 0), (0, W - 1), (H - 1, 0), (H - 1, W - 1)]

    def cdist(p):
        return min(max(abs(p[0] - cy), abs(p[1] - cx)) for cy, cx in corners)

    best, best_score = [], None
    for dy, dx in [(1, 1), (1, -1)]:
        for y in range(H):
            for x in range(W):
                if g[y, x] != fg:
                    continue
                py, px = y - dy, x - dx
                if 0 <= py < H and 0 <= px < W and g[py, px] == fg:
                    continue
                run = []
                cy, cx = y, x
                while 0 <= cy < H and 0 <= cx < W and g[cy, cx] == fg:
                    run.append((cy, cx))
                    cy += dy
                    cx += dx
                score = (len(run), -min(cdist(run[0]), cdist(run[-1])))
                if best_score is None or score > best_score:
                    best, best_score = run, score
    out = g.copy()
    for y, x in best:
        out[y, x] = 8
    emit(out, "Painted the longest unbroken diagonal run of open cells (ties: run touching nearest a corner) with colour 8.")
    return out
